<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {businessApi,useBusinessStore} from '../stores/business';import {useSessionStore} from '../stores/session';import {useRunStore} from '../stores/run';import type {NativeTaskDetail,NativeContext,BusinessResult} from '@shared/business';import BusinessPlanCard from '../components/BusinessPlanCard.vue';import NativeIncidentCard from '../components/business/NativeIncidentCard.vue';import AsyncState from './AsyncState.vue';
const props=defineProps<{taskId:string}>(),business=useBusinessStore(),session=useSessionStore(),run=useRunStore(),detail=ref<NativeTaskDetail>(),card=ref<BusinessResult>(),loading=ref(true),error=ref('');
async function load(){loading.value=true;try{const d=await businessApi<NativeTaskDetail>('proxy/tasks/'+encodeURIComponent(props.taskId));detail.value=d;if(!d.task||d.task.status==='permission_changed')throw new Error('任务属于已变化的授权范围，当前无法办理');const context=await businessApi<NativeContext>('proxy/context');if(!run.inputLocked)session.startDraft();const view=d.task.kind==='resource.patch'?'health':d.task.kind==='schedule.move'?'schedule':d.task.kind.startsWith('duty.')?'duty':d.task.kind.startsWith('issue.')?'issues':d.task.kind.startsWith('closure.')?'closures':'notifications';card.value={summary:'从主系统持久任务恢复',view,planId:d.plan?.id||null,plan:d.plan||undefined,receipt:d.receipt||undefined,task:d.task,taskId:d.task.id,candidates:d.candidateSet?.kind==='schedule.move'?d.candidateSet.candidates:[],candidateSetId:d.candidateSet?.id,context,scopeKey:business.scopeKey,source:'主系统持久任务',queriedAt:new Date().toISOString(),workbenchUrl:'/operations.html?bridge=1'};error.value='';}catch(e){error.value=(e as Error).message;card.value=undefined;}finally{loading.value=false;}}
onMounted(load);watch(()=>props.taskId,load);
</script>
<template><AsyncState :loading="loading" :error="error" @retry="load"><template v-if="detail?.task"><p class="mobile-source">任务 {{detail.task.id}} · 修订 {{detail.task.revision}}</p><NativeIncidentCard v-if="detail.task.kind.startsWith('incident.')" :scope-key="business.scopeKey" :incident-id="detail.task.entityId" :task-id="detail.task.id" :readonly="run.inputLocked"/><BusinessPlanCard v-else-if="card" :key="taskId" :result="card" :card-id="'task:'+taskId" :readonly="run.inputLocked"/></template></AsyncState></template>
